<script setup>
/**
 * MapView.vue - 非遗地图页面
 *
 * 功能说明：
 * - 展示湖北各地非遗传承基地的地图和列表
 * - 左侧CSS模拟地图，带标记点和区域色块
 * - 右侧可滚动的点位列表
 * - 支持按类型和地区筛选
 * - 点击标记点显示信息卡片，点击查看详情弹窗
 * - 点击列表项高亮对应标记点
 */
import { ref, computed, onMounted } from 'vue'
import { useStore } from 'vuex'
import LoadingSpinner from '@/components/LoadingSpinner.vue'
import SkeletonLoader from '@/components/SkeletonLoader.vue'
import EmptyState from '@/components/EmptyState.vue'

// 获取 Vuex store 实例
const store = useStore()

// ==================== 响应式状态 ====================

/** 当前选中的点位类型 */
const selectedType = ref('all')
/** 当前选中的地区 */
const selectedRegion = ref('all')
/** 当前选中的点位ID */
const selectedPointId = ref(null)
/** 是否显示详情弹窗 */
const showDetailModal = ref(false)
/** 详情弹窗中的点位数据 */
const detailPoint = ref(null)

// ==================== 点位类型配置 ====================

/** 点位类型列表，包含标签、值和颜色 */
const pointTypes = [
  { label: '全部', value: 'all', color: '#8B2500' },
  { label: '博物馆', value: 'museum', color: '#E74C3C' },
  { label: '传承工坊', value: 'workshop', color: '#3498DB' },
  { label: '非遗项目', value: 'heritage', color: '#27AE60' },
  { label: '文化遗址', value: 'site', color: '#F39C12' }
]

/** 区域色块配置（CSS模拟地图） */
const regionBlocks = [
  { name: '武汉市', count: 4, style: { top: '35%', left: '45%', width: '18%', height: '14%' } },
  { name: '宜昌市', count: 2, style: { top: '50%', left: '20%', width: '16%', height: '16%' } },
  { name: '襄阳市', count: 2, style: { top: '25%', left: '35%', width: '16%', height: '14%' } },
  { name: '黄冈市', count: 2, style: { top: '40%', left: '65%', width: '16%', height: '14%' } },
  { name: '恩施州', count: 1, style: { top: '65%', left: '15%', width: '14%', height: '18%' } },
  { name: '十堰市', count: 1, style: { top: '15%', left: '25%', width: '14%', height: '14%' } },
  { name: '荆州市', count: 1, style: { top: '55%', left: '40%', width: '16%', height: '12%' } },
  { name: '荆门市', count: 1, style: { top: '38%', left: '48%', width: '14%', height: '12%' } }
]

// ==================== 计算属性 ====================

/** 从 Vuex store 获取加载状态 */
const loading = computed(() => store.state.loading)

/** 从 Vuex store 获取地图点位列表 */
const mapPoints = computed(() => store.state.mapPoints || [])

/** 提取所有地区选项 */
const regions = computed(() => {
  const set = new Set(mapPoints.value.map(p => p.region))
  return Array.from(set).filter(Boolean).sort()
})

/** 根据类型和地区筛选后的点位列表 */
const filteredPoints = computed(() => {
  let result = mapPoints.value
  if (selectedType.value !== 'all') {
    result = result.filter(p => p.type === selectedType.value)
  }
  if (selectedRegion.value !== 'all') {
    result = result.filter(p => p.region === selectedRegion.value)
  }
  return result
})

// ==================== 方法 ====================

/**
 * 设置当前点位类型筛选
 * @param {string} value - 类型值
 */
const setType = (value) => {
  selectedType.value = value
}

/**
 * 获取点位类型的颜色
 * @param {string} type - 类型值
 * @returns {string} 颜色值
 */
const getTypeColor = (type) => {
  const found = pointTypes.find(t => t.value === type)
  return found ? found.color : '#8B2500'
}

/**
 * 获取点位类型的中文标签
 * @param {string} type - 类型值
 * @returns {string} 中文标签
 */
const getTypeLabel = (type) => {
  const found = pointTypes.find(t => t.value === type)
  return found ? found.label : type
}

/**
 * 获取类型的图标文字
 * @param {string} type - 类型值
 * @returns {string} 图标emoji
 */
const typeIcon = (type) => {
  const icons = { museum: '博', workshop: '坊', heritage: '遗', site: '址' }
  return icons[type] || '点'
}

/**
 * 选中点位（点击标记点或列表项）
 * @param {Object} point - 点位数据
 */
const selectPoint = (point) => {
  selectedPointId.value = selectedPointId.value === point.id ? null : point.id
}

/**
 * 打开点位详情弹窗
 * @param {Object} point - 点位数据
 */
const openDetail = (point) => {
  detailPoint.value = point
  showDetailModal.value = true
}

/**
 * 关闭详情弹窗
 */
const closeDetail = () => {
  showDetailModal.value = false
  detailPoint.value = null
}

/**
 * 计算标记点在地图上的位置样式
 * 将经纬度映射为百分比位置（模拟）
 * @param {Object} point - 点位数据
 * @returns {Object} CSS样式对象
 */
const getMarkerStyle = (point) => {
  // 湖北省大致经纬度范围：北纬 29°-33°，东经 108°-116°
  // 映射为CSS百分比位置
  const latMin = 29, latMax = 33
  const lngMin = 108, lngMax = 116
  const top = ((latMax - (point.lat || 30.5)) / (latMax - latMin)) * 80 + 10
  const left = (((point.lng || 112) - lngMin) / (lngMax - lngMin)) * 80 + 10
  return {
    top: `${top}%`,
    left: `${left}%`
  }
}

// ==================== 生命周期 ====================

onMounted(async () => {
  try {
    await store.dispatch('fetchMapPoints')
  } catch (err) {
    console.error('获取地图点位失败:', err)
  }
})
</script>

